import { Pool, PoolClient } from 'pg';
import { Command } from 'commander';
import * as crypto from 'crypto';

interface SessionContext {
  userId: string;
  tenantId: string;
  role: string;
}

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT || '5432'),
  database: process.env.DB_NAME || 'appdb',
  user: process.env.DB_USER || 'appuser',
  password: process.env.DB_PASS || 'secret',
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

async function initConnection(client: PoolClient, ctx: SessionContext): Promise<void> {
  await client.query('SET app.current_user_id = $1', [ctx.userId]);
  await client.query('SET app.current_tenant_id = $1', [ctx.tenantId]);
  await client.query('SET app.current_role = $1', [ctx.role]);
}

async function getDocuments(ctx: SessionContext, filters: { status?: string; limit?: number }): Promise<any[]> {
  const client = await pool.connect();
  try {
    await initConnection(client, ctx);
    const tenantClause = buildTenantFilter(ctx);

    // Validate and clamp the limit to a safe integer; pass as a bound parameter
    // instead of interpolating user input directly into the SQL string.
    let safeLimit = 50;
    if (filters.limit !== undefined && Number.isInteger(filters.limit)) {
      safeLimit = Math.min(Math.max(filters.limit, 1), 1000);
    }

    const params: any[] = [];
    let paramIdx = 1;
    let statusClause = '';
    if (filters.status) {
      statusClause = `AND d.status = $${paramIdx++}`;
      params.push(filters.status);
    }
    const limitParam = `$${paramIdx++}`;
    params.push(safeLimit);

    const query = `
      SELECT d.id, d.title, d.content, d.owner_id, d.tenant_id, d.status
      FROM documents d
      WHERE ${tenantClause}
      ${statusClause}
      ORDER BY d.created_at DESC
      LIMIT ${limitParam}
    `;
    const result = await client.query(query, params);
    return result.rows;
  } finally {
    client.release();
  }
}

function buildTenantFilter(ctx: SessionContext): string {
  if (ctx.role === 'superadmin') {
    return '1=1';
  }
  return `d.tenant_id = current_setting('app.current_tenant_id')`;
}

async function getDocumentById(ctx: SessionContext, documentId: string): Promise<any> {
  const client = await pool.connect();
  try {
    await initConnection(client, ctx);
    const result = await client.query(
      'SELECT id, title, content, owner_id, tenant_id, status FROM documents WHERE id = $1',
      [documentId]
    );
    if (result.rows.length === 0) {
      throw new Error('Document not found');
    }
    const doc = result.rows[0];
    await verifyAccess(client, ctx, doc);
    return doc;
  } finally {
    client.release();
  }
}

async function verifyAccess(client: PoolClient, ctx: SessionContext, doc: any): Promise<void> {
  if (ctx.role === 'superadmin') return;

  if (doc.tenant_id !== ctx.tenantId) {
    throw new Error('Access denied: tenant mismatch');
  }
}

async function updateDocument(
  ctx: SessionContext,
  documentId: string,
  updates: { title?: string; content?: string; status?: string }
): Promise<any> {
  const client = await pool.connect();
  try {
    await initConnection(client, ctx);
    await client.query('BEGIN');

    const existing = await client.query(
      'SELECT id, owner_id, tenant_id FROM documents WHERE id = $1 FOR UPDATE',
      [documentId]
    );

    if (existing.rows.length === 0) {
      await client.query('ROLLBACK');
      throw new Error('Document not found');
    }

    const doc = existing.rows[0];
    await verifyOwnership(client, ctx, doc);

    const setClauses: string[] = [];
    const params: any[] = [];
    let paramIdx = 1;

    if (updates.title) { setClauses.push(`title = $${paramIdx++}`); params.push(updates.title); }
    if (updates.content) { setClauses.push(`content = $${paramIdx++}`); params.push(updates.content); }
    if (updates.status) { setClauses.push(`status = $${paramIdx++}`); params.push(updates.status); }

    if (setClauses.length === 0) {
      await client.query('ROLLBACK');
      throw new Error('No updates provided');
    }

    params.push(documentId);
    const result = await client.query(
      `UPDATE documents SET ${setClauses.join(', ')}, updated_at = NOW() WHERE id = $${paramIdx} RETURNING *`,
      params
    );

    await client.query('COMMIT');
    return result.rows[0];
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

async function verifyOwnership(client: PoolClient, ctx: SessionContext, doc: any): Promise<void> {
  if (ctx.role === 'superadmin') return;
  if (ctx.role === 'admin') {
    if (doc.tenant_id === ctx.tenantId) return;
    throw new Error('Access denied: admin can only modify own tenant documents');
  }
  if (doc.owner_id !== ctx.userId) {
    throw new Error('Access denied: not document owner');
  }
}

async function deleteDocument(ctx: SessionContext, documentId: string): Promise<void> {
  const client = await pool.connect();
  try {
    await initConnection(client, ctx);
    await client.query('BEGIN');

    const existing = await client.query(
      'SELECT id, owner_id, tenant_id FROM documents WHERE id = $1 FOR UPDATE',
      [documentId]
    );

    if (existing.rows.length === 0) {
      await client.query('ROLLBACK');
      throw new Error('Document not found');
    }

    const doc = existing.rows[0];
    await verifyOwnership(client, ctx, doc);

    await client.query('DELETE FROM documents WHERE id = $1', [documentId]);
    await client.query('COMMIT');
  } catch (err) {
    await client.query('ROLLBACK').catch(() => {});
    throw err;
  } finally {
    client.release();
  }
}

async function authenticateUser(token: string): Promise<SessionContext> {
  const client = await pool.connect();
  try {
    const result = await client.query(
      'SELECT u.id, u.tenant_id, u.role FROM users u INNER JOIN sessions s ON s.user_id = u.id WHERE s.token_hash = $1 AND s.expires_at > NOW()',
      [crypto.createHash('sha256').update(token).digest('hex')]
    );
    if (result.rows.length === 0) {
      throw new Error('Invalid or expired session');
    }
    return {
      userId: result.rows[0].id,
      tenantId: result.rows[0].tenant_id,
      role: result.rows[0].role,
    };
  } finally {
    client.release();
  }
}

const program = new Command();

program
  .name('docctl')
  .description('Document management CLI')
  .requiredOption('-t, --token <token>', 'Authentication token');

program
  .command('list')
  .option('-s, --status <status>', 'Filter by status')
  .option('-l, --limit <limit>', 'Limit results', '50')
  .action(async (opts) => {
    const token = program.opts().token;
    const ctx = await authenticateUser(token);
    const docs = await getDocuments(ctx, { status: opts.status, limit: parseInt(opts.limit) });
    console.table(docs);
  });

program
  .command('get <id>')
  .action(async (id) => {
    const token = program.opts().token;
    const ctx = await authenticateUser(token);
    const doc = await getDocumentById(ctx, id);
    console.log(JSON.stringify(doc, null, 2));
  });

program
  .command('update <id>')
  .option('--title <title>', 'New title')
  .option('--content <content>', 'New content')
  .option('--status <status>', 'New status')
  .action(async (id, opts) => {
    const token = program.opts().token;
    const ctx = await authenticateUser(token);
    const doc = await updateDocument(ctx, id, opts);
    console.log('Updated:', JSON.stringify(doc, null, 2));
  });

program
  .command('delete <id>')
  .action(async (id) => {
    const token = program.opts().token;
    const ctx = await authenticateUser(token);
    await deleteDocument(ctx, id);
    console.log('Deleted successfully');
  });

program.parseAsync(process.argv).catch((err) => {
  console.error('Error:', err.message);
  process.exit(1);
});
